import { writeFileSync, mkdirSync } from 'node:fs'
const [,, base, outDir] = process.argv
mkdirSync(outDir, { recursive: true })
const cart = encodeURIComponent(JSON.stringify([{ slug: 'notebook', qty: 2 }]))
const cases = [
  ['empty', '', ['/', '/cart', '/checkout', '/products/notebook']],
  ['full', `cart=${cart}`, ['/', '/cart', '/checkout', '/products/notebook']],
]
for (const [name, cookie, paths] of cases) {
  for (const p of paths) {
    const res = await fetch(base + p, { redirect: 'manual', headers: cookie ? { cookie } : {} })
    const body = await res.text()
    const file = `${outDir}/${name}${p.replace(/\//g, '_') || '_'}.html`
    writeFileSync(file, body)
    console.log(name, p, res.status, res.headers.get('location') ?? '', body.length)
  }
}
EOF
